notices contains {"rule_id": "o6_9.premium.separation_cap_20_m3_per_gve", "message": sprintf("Separierte Menge %v m³ über Obergrenze %v m³ (20 m³ je Rinder-GVE).", [declared_separation_m3, separation_cap_m3])} if {
