# Strongly nitrogen-reduced feeding of pigs (from application year 2025).
package oepul.o6_9

cp := data.o6_9

pig_feeding := object.get(input, ["livestock", "pig_feeding"], {})

rations := object.get(pig_feeding, "rations", [])

# Arable area for the density threshold: total arable area without deductions.
arable_area_total_ha := input.land.arable_area_ha if is_number(input.land.arable_area_ha)

else := sum([p.area_ha | some p in parcels; p.land_use == "arable"])

pig_gve_per_arable_ha := pig_gve / arable_area_total_ha if arable_area_total_ha > 0

else := 0

default n_feeding_density_met := false

n_feeding_density_met if pig_gve_per_arable_ha >= params.n_feeding.min_pig_gve_per_arable_ha

protein_limit(category) := row.max_g_per_kg_88dm if {
	some row in cp.crude_protein_limits
	row.animal_category == category
}

ration_compliant(r) if r.crude_protein_g_per_kg_88dm <= protein_limit(r.animal_category)

fattening_categories := {c | some c in cp.fattening_phase_categories} | {"fattening_average"}

fattening_rations := [r | some r in rations; r.animal_category in fattening_categories]

phase_rations := [r | some r in rations; r.animal_category in {c | some c in cp.fattening_phase_categories}]

# Fattening pigs / non-mated gilts: either the average value or the phase
# limits must be met, not both.
default fattening_compliant := false

fattening_compliant if count(fattening_rations) == 0

fattening_compliant if {
	some r in rations
	r.animal_category == "fattening_average"
	ration_compliant(r)
}

fattening_compliant if {
	count(phase_rations) > 0
	every r in phase_rations {
		ration_compliant(r)
	}
}

non_fattening_rations_compliant if {
	every r in rations {
		ration_ok_or_fattening(r)
	}
}

ration_ok_or_fattening(r) if r.animal_category in fattening_categories

ration_ok_or_fattening(r) if ration_compliant(r)

unknown_ration_categories contains r.animal_category if {
	some r in rations
	not protein_limit(r.animal_category)
}

default protein_limits_met := false

protein_limits_met if {
	pig_feeding.all_pigs_covered == true
	count(rations) > 0
	count(unknown_ration_categories) == 0
	non_fattening_rations_compliant
	fattening_compliant
}

valid_protein_source(s) if {
	some row in cp.protein_value_sources
	row.source == s
}

default n_feeding_eligible := false

n_feeding_eligible if {
	participates_n_feeding
	n_feeding_density_met
	protein_limits_met
	not n_feeding_combination_conflict
}

# Premium basis: arable parcels (no national park, no OP code, harvest obligation met).
parcel_has_op_code(p) if {
	"OP" in object.get(p, "oepul_codes", [])
}

parcel_in_national_park(p) if object.get(p, ["constraints", "in_national_park"], false) == true

n_feeding_premium_parcel(p) if {
	p.land_use == "arable"
	parcel_in_austria(p)
	not parcel_in_national_park(p)
	not parcel_has_op_code(p)
	harvest_obligation_met(p)
}

n_feeding_premium_area_ha := sum([p.area_ha | some p in parcels; n_feeding_premium_parcel(p)]) if count(parcels) > 0

else := arable_area_total_ha

# General ÖPUL conditions applicable to o6_9 (applicant, farm size,
# minimum management, 2026 drought relief, sanctions).
package oepul.o6_9

applicant := object.get(input, ["farm", "applicant"], {})

# Eligible applicants: natural persons, registered partnerships, legal persons
# and associations of persons (public-body share max. 25 %); active farmer.
default applicant_eligible := false

applicant_eligible if {
	some lf in general.applicant_legal_forms
	lf.legal_form == applicant.legal_form
	public_body_share_ok(lf)
	applicant.is_active_farmer == true
}

public_body_share_ok(lf) if lf.public_body_share_limit_applies == false

public_body_share_ok(lf) if {
	lf.public_body_share_limit_applies == true
	number_or_zero(object.get(applicant, "public_body_share_percent", 0)) <= params.applicant.max_public_body_share_percent
}

# Minimum farm size applies only in the first year of ÖPUL participation.
default first_year_min_size_met := false

first_year_min_size_met if input.farm.oepul_first_participation_year != year

first_year_min_size_met if {
	input.farm.oepul_first_participation_year == year
	number_or_zero(object.get(input, ["land", "protected_cultivation_area_ha"], 0)) >= params.first_year_min_farm_size.protected_cultivation_min_ha
}

first_year_min_size_met if {
	input.farm.oepul_first_participation_year == year
	total_area_ha >= params.first_year_min_farm_size.agricultural_area_min_ha
}

# 2026 drought: no harvest needed in listed districts if no harvestable crop.
parcel_district(p) := p.district if is_string(p.district)

else := input.farm.region.district

drought_district_listed(state, district) if {
	some row in data.o6_9.drought_2026.harvest_exemption_districts
	row.federal_state == state
	row.district in {"*", district}
}

drought_harvest_exempt(p) if {
	year == data.o6_9.drought_2026.year
	drought_district_listed(input.farm.region.federal_state, parcel_district(p))
	object.get(p, ["operations", "no_harvestable_crop_due_to_drought"], false) == true
}

# Minimum management on arable land: harvest on at least 85 % of the parcel.
harvest_obligation_met(p) if object.get(p, ["operations", "harvested_share_percent"], 100) >= data.o6_9.drought_2026.harvest_obligation_min_share_percent

harvest_obligation_met(p) if drought_harvest_exempt(p)

# Area payment cap per parcel (sum of area-related ÖPUL payments).
area_payment_cap_eur_per_ha(y) := row.eur_per_ha if {
	some row in general.area_payment_caps
	row.scope == "general"
	row.valid_from <= y
	cap_row_valid_to(row, y)
}

cap_row_valid_to(row, _) if row.valid_to == null

cap_row_valid_to(row, y) if {
	row.valid_to != null
	y <= row.valid_to
}

# Sanction stages for breaches of content obligations; from 2027 the
# warning is replaced by a 1 % retention.
sanction_reduction_share(stage, y) := row.reduction_share if {
	y < 2027
	some row in general.sanction_stages
	row.stage == stage
}

sanction_reduction_share(stage, y) := row.reduction_share_from_2027 if {
	y >= 2027
	some row in general.sanction_stages
	row.stage == stage
}

# Near-ground application of liquid farm manure and biogas slurry.
package oepul.o6_9

defs := data.o6_9.manure_definitions

application_records := object.get(manure, "applications", [])

eligible_manure_kind(kind) if {
	some e in defs.eligible_manure_kinds
	e.kind == kind
}

eligible_technique(technique) if technique in {t | some t in defs.eligible_techniques}

excluded_technique(technique) if {
	some e in defs.excluded_techniques
	e.technique == technique
}

permitted_biogas_input(input_id) if {
	some i in defs.biogas_permitted_inputs
	i.input_id == input_id
}

biogas_inputs := object.get(manure, "biogas_inputs", [])

biogas_excluded_components := object.get(manure, "biogas_excluded_components_present", [])

# Any component outside the definition disqualifies the entire biogas slurry.
default biogas_ineligible := false

biogas_ineligible if {
	some i in biogas_inputs
	not permitted_biogas_input(i)
}

biogas_ineligible if count(biogas_excluded_components) > 0

record_parcel_ids(r) := r.parcel_ids if is_array(r.parcel_ids)

else := [r.parcel_id]

# Application must take place on arable or grassland parcels of the farm.
record_on_eligible_parcels(r) if {
	ids := record_parcel_ids(r)
	count(ids) > 0
	every id in ids {
		p := parcel_index[id]
		p.land_use in {x | some x in params.eligible_land_uses_for_application}
		parcel_in_austria(p)
	}
}

record_ineligibility_reasons(r) := {reason |
	some check in [
		[fails_manure_kind(r), "manure_kind_not_eligible"],
		[fails_technique(r), "technique_not_eligible"],
		[fails_parcel(r), "parcel_not_farm_arable_or_grassland"],
		[fails_biogas(r), "biogas_slurry_outside_definition"],
		[fails_volume(r), "no_positive_volume"],
	]
	check[0] == true
	reason := check[1]
}

fails_manure_kind(r) := false if eligible_manure_kind(r.manure_kind)

else := true

fails_technique(r) := false if eligible_technique(r.technique)

else := true

fails_parcel(r) := false if record_on_eligible_parcels(r)

else := true

fails_biogas(r) if {
	r.manure_kind == "biogasguelle"
	biogas_ineligible
}

else := false

fails_volume(r) := false if r.volume_m3 > 0

else := true

record_eligible(r) if count(record_ineligibility_reasons(r)) == 0

recorded_eligible_m3(technique) := sum([r.volume_m3 |
	some r in application_records
	r.technique == technique
	record_eligible(r)
])

ineligible_application_records contains {"index": i, "reasons": record_ineligibility_reasons(r)} if {
	some i, r in application_records
	not record_eligible(r)
}

# Chronological, parcel-related record fields.
required_record_fields := ["date", "manure_kind", "volume_m3", "technique"]

record_complete(r) if {
	every f in required_record_fields {
		object.get(r, f, null) != null
	}
	count(record_parcel_ids(r)) > 0
}

# Several parcels may be summarised if crop, quantity, date and technique are identical.
records_groupable(a, b) if {
	a.crop_name == b.crop_name
	a.volume_m3_per_ha == b.volume_m3_per_ha
	a.date == b.date
	a.technique == b.technique
}

# Summarised records must state the added-up parcel sizes.
grouped_record_area_ok(r) if {
	not is_array(object.get(r, "parcel_ids", null))
}

grouped_record_area_ok(r) if {
	is_array(r.parcel_ids)
	expected := sum([parcel_index[id].area_ha | some id in r.parcel_ids])
	abs(expected - number_or_zero(object.get(r, "area_ha", 0))) < 0.0001
}

records_chronological if {
	dates := [r.date | some r in application_records]
	dates == sort(dates)
}

# Fertilisable area: arable and grassland with nitrogen demand according to
# NAPV; pure legume stands and parcels with a total fertilisation ban excluded.
has_pure_legume_flag(p) if is_boolean(p.crop.is_pure_legume_stand)

pure_legume_stand(p) if p.crop.is_pure_legume_stand == true

pure_legume_stand(p) if {
	not has_pure_legume_flag(p)
	p.crop.crop_category == "legume"
}

fertilisable_parcel(p) if {
	p.land_use in {"arable", "grassland"}
	parcel_in_austria(p)
	not pure_legume_stand(p)
	object.get(p, ["constraints", "total_fertilization_ban"], false) != true
	object.get(p, ["constraints", "has_n_fertilization_need"], true) != false
}

fertilisable_area_ha := sum([p.area_ha | some p in parcels; fertilisable_parcel(p)])

slurry_cap_m3 := params.caps.slurry_m3_per_fertilizable_ha * fertilisable_area_ha

# The cap refers to the total near-ground volume; when exceeded, all
# techniques are reduced proportionally (assumption A-03).
default slurry_scale := 1

slurry_scale := slurry_cap_m3 / declared_slurry_total_m3 if declared_slurry_total_m3 > slurry_cap_m3

eligible_slurry_m3(category) := declared_m3(category) * slurry_scale if volumes_declared_in_time

else := 0

default slurry_cap_exceeded := false

slurry_cap_exceeded if declared_slurry_total_m3 > slurry_cap_m3

